    output  [ARSIZE_WID-1:0] ARSIZEsi2mi6;  
    output  [ARBURST_WID-1:0] ARBURSTsi2mi6; 
//ENABLE_LOCK_ReadOutput
    output  [ARLOCK_WID-1:0] ARLOCKsi2mi6;  
//ENABLE_CACHE_ReadOutput
    output  [ARCACHE_WID-1:0] ARCACHEsi2mi6; 
//ENABLE_PROT_ReadOutput
    output  [ARPROT_WID-1:0] ARPROTsi2mi6;  

    //For Master interface SlaveNum = 7
    //Write address channel
    output  [MASTERID_WID-1:0] ARIDsi2mi7;    
    output  [ADDR_WID-1:0] ARADDRsi2mi7;  
    output  [ARLEN_WID-1:0] ARLENsi2mi7;   
    output  [ARSIZE_WID-1:0] ARSIZEsi2mi7;  
    output  [ARBURST_WID-1:0] ARBURSTsi2mi7; 
//ENABLE_LOCK_ReadOutput
    output  [ARLOCK_WID-1:0] ARLOCKsi2mi7;  
//ENABLE_CACHE_ReadOutput
    output  [ARCACHE_WID-1:0] ARCACHEsi2mi7; 
//ENABLE_PROT_ReadOutput
    output  [ARPROT_WID-1:0] ARPROTsi2mi7;  


//Default Slave Number = 8    //For Master interface SlaveNum = 8
    //Write address channel
    output  [MASTERID_WID-1:0] ARIDsi2mi8;    
    output  [ADDR_WID-1:0] ARADDRsi2mi8;  
