//ENABLE_CACHE_ReadOutput
    output  [ARCACHE_WID-1:0] ARCACHEsi2mi8; 
//ENABLE_PROT_ReadOutput
    output  [ARPROT_WID-1:0] ARPROTsi2mi8;  

////////////////////////////

    output  [SLAVE_NUM-1:0]ARVALIDsi2mi; 
    input   [SLAVE_NUM-1:0]ARREADYmi2si; 

    //From SI(slave interface)
    
    //Slave3
    //__________________________________________________
    input   [MASTERID_WID-1:0]    RIDmi32si;     
    input   [RRESP_WID-1:0] RRESPmi32si;   
    input   [BUS_WID-1:0]   RDATAmi32si;

    
    //Slave6
    //__________________________________________________
    input   [MASTERID_WID-1:0]    RIDmi62si;     
    input   [RRESP_WID-1:0] RRESPmi62si;   
    input   [BUS_WID-1:0]   RDATAmi62si;

    
    //Slave7
    //__________________________________________________
    input   [MASTERID_WID-1:0]    RIDmi72si;     
    input   [RRESP_WID-1:0] RRESPmi72si;   
    input   [BUS_WID-1:0]   RDATAmi72si;


//Default Slave Number = 8    
    //Slave8
    //__________________________________________________
    input   [MASTERID_WID-1:0]    RIDmi82si;     
    input   [RRESP_WID-1:0] RRESPmi82si;   
    input   [BUS_WID-1:0]   RDATAmi82si;

////////////////////////////

    input   [SLAVE_NUM-1:0] RVALIDmi2si;  
    input   [SLAVE_NUM-1:0] RLASTmi2si;  
    output  [SLAVE_NUM-1:0] RREADYsi2mi;    


    wire [SLAVE_WID :0] CtlData2writech;

