    //SLAVE 6
    assign  ARIDsi2mi6 = ARIDm2si;    
    assign  ARADDRsi2mi6 = ARADDRm2si;  
    assign  ARLENsi2mi6 = ARLENm2si;   
    assign  ARSIZEsi2mi6 = ARSIZEm2si;  
    assign  ARBURSTsi2mi6 = ARBURSTm2si; 
    assign  ARLOCKsi2mi6 = ARLOCKm2si;  
    assign  ARCACHEsi2mi6 = ARCACHEm2si; 
    assign  ARPROTsi2mi6 = ARPROTm2si;  

    //SLAVE 7
    assign  ARIDsi2mi7 = ARIDm2si;    
