    //SLAVE 8
    assign  ARIDsi2mi8 = ARIDm2si;    
    assign  ARADDRsi2mi8 = ARADDRm2si;  
    assign  ARLENsi2mi8 = ARLENm2si;   
    assign  ARSIZEsi2mi8 = ARSIZEm2si;  
    assign  ARBURSTsi2mi8 = ARBURSTm2si; 
    assign  ARLOCKsi2mi8 = ARLOCKm2si;  
    assign  ARCACHEsi2mi8 = ARCACHEm2si; 
    assign  ARPROTsi2mi8 = ARPROTm2si;  



//Read address channel
//____________________________________________________________________

//ARVALID MUX 
reg [SLAVE_NUM-1:0]ARVALIDsi2mi; 

//MUX TYPE 00 was Generated 
always @(CtlData2writech  or 
         ARVALIDm2si  )
begin

    if(CtlData2writech [SLAVE_WID]) //MUX enalbe bit
    begin
        case(CtlData2writech [SLAVE_WID-1:0])
        //synopsys parallel_case full_case
            4'd3:   
            begin
                 ARVALIDsi2mi[3] <= ARVALIDm2si ;
                 ARVALIDsi2mi[6] <= 1'b0;
                 ARVALIDsi2mi[7] <= 1'b0;
                 ARVALIDsi2mi[8] <= 1'b0;
            end
            4'd6:   
            begin
                 ARVALIDsi2mi[3] <= 1'b0;
                 ARVALIDsi2mi[6] <= ARVALIDm2si ;
                 ARVALIDsi2mi[7] <= 1'b0;
                 ARVALIDsi2mi[8] <= 1'b0;
            end
            4'd7:   
            begin
                 ARVALIDsi2mi[3] <= 1'b0;
                 ARVALIDsi2mi[6] <= 1'b0;
                 ARVALIDsi2mi[7] <= ARVALIDm2si ;
                 ARVALIDsi2mi[8] <= 1'b0;
            end
            default:
            begin
                ARVALIDsi2mi[3] <= 1'b0;
                ARVALIDsi2mi[6] <= 1'b0;
                ARVALIDsi2mi[7] <= 1'b0;
                ARVALIDsi2mi[8] <= ARVALIDm2si ;
            end
        endcase
    end
    else
    begin
        ARVALIDsi2mi[3] <= 1'b0;
        ARVALIDsi2mi[6] <= 1'b0;
        ARVALIDsi2mi[7] <= 1'b0;
        ARVALIDsi2mi[8] <= 1'b0;
    end
end


reg ARREADYsi2m;

//ARREADY Demux
always @(CtlData2writech or ARREADYmi2si)
begin
    if(CtlData2writech[SLAVE_WID])
    begin
        case(CtlData2writech[SLAVE_WID-1:0])
        // synopsys parallel_case full_case
            4'd3:   ARREADYsi2m <= ARREADYmi2si[3]; 
            4'd6:   ARREADYsi2m <= ARREADYmi2si[6]; 
            4'd7:   ARREADYsi2m <= ARREADYmi2si[7]; 
            4'd8:   ARREADYsi2m <= ARREADYmi2si[8]; 
            default:
                ARREADYsi2m <= 1'b0;
        endcase
    end
    else
        ARREADYsi2m <= 1'b0;
end

reg [SLAVE_WID-1:0] SlaveNum;

//ADDRESS Decoder
//____________________________________________________________________

//Slave Number 3
wire Slave3MAX0En = (ARADDRm2si >= 32'h60000000) ? 1'b1:1'b0;
wire Slave3MIN0En = (32'h70000000 >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave3_0En = Slave3MAX0En & Slave3MIN0En;

//Slave Number 6
wire Slave6MAX0En = (ARADDRm2si >= 32'h0) ? 1'b1:1'b0;
wire Slave6MIN0En = (32'h20000000 >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave6_0En = Slave6MAX0En & Slave6MIN0En;

//Slave Number 7
wire Slave7MAX0En = (ARADDRm2si >= 32'h20000000) ? 1'b1:1'b0;
wire Slave7MIN0En = (32'h30000000 >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave7_0En = Slave7MAX0En & Slave7MIN0En;


//Slave Number 3
wire Slave3MAX1En = (ARADDRm2si >= 32'h60000000) ? 1'b1:1'b0;
wire Slave3MIN1En = (32'h70000000 >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave3_1En = Slave3MAX1En & Slave3MIN1En;

//Selection mux
wire Slave3En = (SelMAP1) ? Slave3_1En : Slave3_0En;

//Slave Number 6
wire Slave6MAX1En = (ARADDRm2si >= 32'h20000000) ? 1'b1:1'b0;
wire Slave6MIN1En = (32'h40000000 >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave6_1En = Slave6MAX1En & Slave6MIN1En;

//Selection mux
wire Slave6En = (SelMAP1) ? Slave6_1En : Slave6_0En;

//Slave Number 7
wire Slave7MAX1En = (ARADDRm2si >= 32'h0) ? 1'b1:1'b0;
wire Slave7MIN1En = (32'h10000000 >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave7_1En = Slave7MAX1En & Slave7MIN1En;

//Selection mux
wire Slave7En = (SelMAP1) ? Slave7_1En : Slave7_0En;



wire Slave8En = 
                !Slave3En &
                !Slave6En &
                !Slave7En ;

always @(
         Slave3En or
         Slave6En or
         Slave7En or
         Slave8En  
        )
begin
    case(1'b1) //synopsys parallel_case
        Slave3En:   SlaveNum <= 4'd3;
        Slave6En:   SlaveNum <= 4'd6;
        Slave7En:   SlaveNum <= 4'd7;
        Slave8En:   SlaveNum <= 4'd8;
        default:   SlaveNum <= {4{1'd0}};
    endcase
end

//STATE_END

//____________________________________________________________________

//Read data channel
//____________________________________________________________________

reg   [MASTERID_WID-1:0]RIDsi2m;     
reg   [RRESP_WID-1:0]   RRESPsi2m;   
reg   RVALIDsi2m;  
reg   RLASTsi2m;
reg   [SLAVE_NUM-1:0]   RREADYsi2mi;    
reg   [BUS_WID-1:0]     RDATAsi2m;

//Data Arbiter
reg   [SLAVE_WID-1:0] CtlData2readch; 

//Response Arbiter
//Arbiter was Generated TYPE00
reg   EnArbiter;

always @(
         RVALIDmi2si or
         CtlData2readch
        )
begin
    case(CtlData2readch)
        //synopsys parallel_case full_case
        4'd3:    EnArbiter <= RVALIDmi2si[3];
        4'd6:    EnArbiter <= RVALIDmi2si[6];
        4'd7:    EnArbiter <= RVALIDmi2si[7];
        4'd8:    EnArbiter <= RVALIDmi2si[8];
        default: EnArbiter <= 1'b0;
    endcase
end

always  @(posedge ACLK or negedge ARESETn)
begin
    if(!ARESETn)
    begin
        CtlData2readch <= 0;
    end
    else if(!EnArbiter)
    begin
          if(RVALIDmi2si[3]) CtlData2readch <= 4'd3;
          else if(RVALIDmi2si[6]) CtlData2readch <= 4'd6;
          else if(RVALIDmi2si[7]) CtlData2readch <= 4'd7;
          else if(RVALIDmi2si[8]) CtlData2readch <= 4'd8;
    end
end



//MUX TYPE 01 was Generated 
always @(CtlData2readch[SLAVE_WID-1:0]  or 
         RREADYm2si  )
begin

   case(CtlData2readch[SLAVE_WID-1:0] )
   //synopsys parallel_case full_case
        4'd3:   
            begin
                 RREADYsi2mi[3] <= RREADYm2si ;
                 RREADYsi2mi[6] <= 1'b0;
                 RREADYsi2mi[7] <= 1'b0;
                 RREADYsi2mi[8] <= 1'b0;
            end
        4'd6:   
            begin
                 RREADYsi2mi[3] <= 1'b0;
                 RREADYsi2mi[6] <= RREADYm2si ;
                 RREADYsi2mi[7] <= 1'b0;
                 RREADYsi2mi[8] <= 1'b0;
            end
        4'd7:   
            begin
                 RREADYsi2mi[3] <= 1'b0;
                 RREADYsi2mi[6] <= 1'b0;
                 RREADYsi2mi[7] <= RREADYm2si ;
                 RREADYsi2mi[8] <= 1'b0;
            end
         default:
            begin
                RREADYsi2mi[3] <= 1'b0;
                RREADYsi2mi[6] <= 1'b0;
                RREADYsi2mi[7] <= 1'b0;
                RREADYsi2mi[8] <= RREADYm2si ;
            end
   endcase
end


    always @(//1
             RRESPmi32si or    
             RRESPmi62si or    
             RRESPmi72si or    
             RRESPmi82si or    
             CtlData2readch
            )
    begin
        case(CtlData2readch[SLAVE_WID-1:0])
            // synopsys parallel_case full_case
            4'd3:   RRESPsi2m  <= RRESPmi32si;
            4'd6:   RRESPsi2m  <= RRESPmi62si;
            4'd7:   RRESPsi2m  <= RRESPmi72si;
            4'd8:   RRESPsi2m  <= RRESPmi82si;
            default:     RRESPsi2m  <= 0;
        endcase
    end


    always @(//2
             RIDmi32si or    
             RIDmi62si or    
             RIDmi72si or    
             RIDmi82si or    
             CtlData2readch
            )
    begin
        case(CtlData2readch[SLAVE_WID-1:0])
            // synopsys parallel_case full_case
            4'd3:   RIDsi2m  <= RIDmi32si;
            4'd6:   RIDsi2m  <= RIDmi62si;
            4'd7:   RIDsi2m  <= RIDmi72si;
            4'd8:   RIDsi2m  <= RIDmi82si;
            default:     RIDsi2m  <= 0;
        endcase
    end


    always @(//3
             RDATAmi32si or    
             RDATAmi62si or    
             RDATAmi72si or    
             RDATAmi82si or    
             CtlData2readch
            )
    begin
        case(CtlData2readch[SLAVE_WID-1:0])
            // synopsys parallel_case full_case
            4'd3:   RDATAsi2m  <= RDATAmi32si;
            4'd6:   RDATAsi2m  <= RDATAmi62si;
            4'd7:   RDATAsi2m  <= RDATAmi72si;
            4'd8:   RDATAsi2m  <= RDATAmi82si;
            default:     RDATAsi2m  <= 0;
        endcase
    end


    always @(//4
             RVALIDmi2si or    
             CtlData2readch
            )
    begin
        case(CtlData2readch[SLAVE_WID-1:0])
            // synopsys parallel_case full_case
            4'd3:   RVALIDsi2m  <= RVALIDmi2si[3];
            4'd6:   RVALIDsi2m  <= RVALIDmi2si[6];
            4'd7:   RVALIDsi2m  <= RVALIDmi2si[7];
            4'd8:   RVALIDsi2m  <= RVALIDmi2si[8];
            default:     RVALIDsi2m  <= 0;
        endcase
    end


    always @(//5
             RLASTmi2si or    
             CtlData2readch
            )
    begin
        case(CtlData2readch[SLAVE_WID-1:0])
            // synopsys parallel_case full_case
            4'd3:   RLASTsi2m  <= RLASTmi2si[3];
            4'd6:   RLASTsi2m  <= RLASTmi2si[6];
            4'd7:   RLASTsi2m  <= RLASTmi2si[7];
            4'd8:   RLASTsi2m  <= RLASTmi2si[8];
            default:     RLASTsi2m  <= 0;
        endcase
    end

RDCH_MAC_PermitCtl 
    U1PermitCtl(

    .ACLK       (ACLK)      ,
    .ARESETn    (ARESETn)   ,
    .SlaveNum   (SlaveNum)  ,

    .SID        (ARIDm2si),
    .AREADY     (ARREADYsi2m),
    .AVALID     (ARVALIDm2si),    

    .WID        ({MASTERID_WID{1'b0}}),
    .WREADY     (1'b0),
    .WVALID     (1'b0),
    .WLAST      (1'b0),

    .LID        (RIDsi2m),
    .LAST       (RLASTsi2m),
    .READY      (RREADYm2si),
    .RVALID     (RVALIDsi2m),

    .CtlData2datach  (),
